te": "- Undergraduate or Graduate Transcripts (must be translated);", "kind": "factual", "statement": "The transcripts must be translated."}, {"claim_id": "u3.c1", "unit_id": "u3", "quote": "- The course(s) used to waive DS-GA 1002 should be highlighted on the transcript, and the grades received should also be highlighted;", "kind": "factual", "statement": "The course or courses used to waive DS-GA 1002 should be highlighted on the transcript."}, {"claim_id": "u3.c2", "unit_id": "u3", "quote": "- The course(s) used to waive DS-GA 1002 should be highlighted on the transcript, and the grades received should also be highlighted;", "kind": "factual", "statement": "The grades received for those courses should also be highlighted."}, {"claim_id": "u4.c1", "unit_id": "u4", "quote": "- Syllabi of the course(s) used for the waiver (must be translated);", "kind": "factual", "statement": "The materials include syllabi for the course or courses used for the waiver."}, {"claim_id": "u4.c2", "unit_id": "u4", "quote": "- Syllabi of the course(s) used for the waiver (must be translated);", "kind": "factual", "statement": "Those syllabi must be translated."}, {"claim_id": "u5.c1", "unit_id": "u5", "quote": "- If available, the course website [1].", "kind": "factual", "statement": "The course website should be provided if it is available."}]}

